import React, { useState, useEffect, useCallback, useRef } from 'react';
import { 
  Users, Calendar, ClipboardCheck, LayoutDashboard, Settings, LogOut, Menu, X, Trophy, Bell, RefreshCw, User, CloudCheck, Cloud, Map, Sparkles, Package, FilePieChart, FileDown
} from 'lucide-react';
import { createClient } from '@supabase/supabase-js';
import { AppUser, AppState, Person, AppNotification, Match, WarehouseItem, TrainingSession, AttendanceRecord, TechnicalReport } from './types';
import html2pdf from 'html2pdf.js';

// Components
import Dashboard from './components/Dashboard';
import SquadManagement from './components/SquadManagement';
import AttendanceTracker from './components/AttendanceTracker';
import TrainingPlanner from './components/TrainingPlanner';
import MatchPlanner from './components/MatchPlanner';
import SettingsView from './components/SettingsView';
import PlayerReport from './components/PlayerReport';
import WarehouseManagement from './components/WarehouseManagement';
import Login from './components/Login';
import ClubLogo from './components/ClubLogo';
import LocationAssistant from './components/LocationAssistant';
import AIAssistant from './components/AIAssistant';
import ChatBot from './components/ChatBot';
import TechnicalReports from './components/TechnicalReports';

// --- Global Utilities ---
export const generateUUID = () => {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) return crypto.randomUUID();
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = Math.random() * 16 | 0;
    return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
  });
};

const supabaseUrl = 'https://kfwqoigsghlgigjriyxf.supabase.co';
const supabaseAnonKey = 'sb_publishable_O2vR2yKUG-FVeaydD4z6Lg_tjFcKDic';
export const supabase = createClient(supabaseUrl, supabaseAnonKey);

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedMatchId, setSelectedMatchId] = useState<string | null>(null);
  const [selectedPlayer, setSelectedPlayer] = useState<Person | null>(null);
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [syncStatus, setSyncStatus] = useState<'synced' | 'error' | 'syncing'>('synced');
  const isInternalUpdate = useRef(false);

  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('alkarama_secure_v10');
    if (saved) {
      try { return JSON.parse(saved); } catch (e) { console.error(e); }
    }
    return {
      currentUser: null,
      categories: ['الرجال', 'الشباب', 'الناشئين', 'الأشبال'],
      people: [],
      sessions: [],
      matches: [],
      warehouse: [],
      technicalReports: [],
      attendance: [],
      users: [],
      notifications: [],
      globalCategoryFilter: 'الكل'
    };
  });

  const handleExportPDF = (elementId: string, title: string) => {
    const element = document.getElementById(elementId);
    if (!element) return;

    addLog("جاري تحضير تقرير PDF احترافي...", "", "info");

    const opt = {
      margin: [10, 5, 10, 5],
      filename: `${title}_${new Date().toLocaleDateString('ar-EG')}.pdf`,
      image: { type: 'jpeg', quality: 0.98 },
      html2canvas: { scale: 2, useCORS: true, letterRendering: true },
      jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' },
      pagebreak: { mode: ['avoid-all', 'css', 'legacy'] }
    };

    html2pdf().set(opt).from(element).save().then(() => {
      addLog("تم تصدير التقرير بنجاح", "جاهز للطباعة", "success");
    });
  };

  useEffect(() => {
    localStorage.setItem('alkarama_secure_v10', JSON.stringify(state));
  }, [state]);

  const addLog = useCallback((message: string, details?: string, type: AppNotification['type'] = 'info') => {
    const newNotif: AppNotification = { id: generateUUID(), message, details, type, timestamp: Date.now(), isRead: false };
    setState(prev => ({ ...prev, notifications: [newNotif, ...prev.notifications].slice(0, 50) }));
  }, []);

  const fetchData = useCallback(async () => {
    if (!state.currentUser) return;
    setIsSyncing(true);
    setSyncStatus('syncing');
    isInternalUpdate.current = true;

    try {
      const [cats, ppl, sess, mtch, attn, wrhs, tech, usrs] = await Promise.all([
        supabase.from('categories').select('*'),
        supabase.from('people').select('*'),
        supabase.from('sessions').select('*'),
        supabase.from('matches').select('*'),
        supabase.from('attendance').select('*'),
        supabase.from('warehouse').select('*'),
        supabase.from('technical_reports').select('*'),
        supabase.from('app_users').select('*')
      ]);

      setState(prev => ({
        ...prev,
        categories: cats.data?.map(c => c.name) || prev.categories,
        people: ppl.data || [],
        sessions: sess.data || [],
        matches: mtch.data || [],
        attendance: attn.data || [],
        warehouse: wrhs.data || [],
        technicalReports: tech.data || [],
        users: usrs.data || []
      }));
      setSyncStatus('synced');
    } catch (error) {
      setSyncStatus('error');
    } finally {
      setIsSyncing(false);
      setTimeout(() => { isInternalUpdate.current = false; }, 1000);
    }
  }, [state.currentUser]);

  const updateStateAndSync = useCallback(async (updater: (prev: AppState) => AppState) => {
    if (!state.currentUser) return;
    const nextState = updater(state);
    setState(nextState);
    setSyncStatus('syncing');
    isInternalUpdate.current = true;

    try {
      const tasks: any[] = [];
      if (nextState.people !== state.people) tasks.push(supabase.from('people').upsert(nextState.people));
      if (nextState.matches !== state.matches) tasks.push(supabase.from('matches').upsert(nextState.matches));
      if (nextState.categories !== state.categories) {
          const catObjects = nextState.categories.map(c => ({ name: c }));
          tasks.push(supabase.from('categories').upsert(catObjects, { onConflict: 'name' }));
      }
      if (nextState.attendance !== state.attendance) tasks.push(supabase.from('attendance').upsert(nextState.attendance));
      if (nextState.warehouse !== state.warehouse) tasks.push(supabase.from('warehouse').upsert(nextState.warehouse));
      if (nextState.technicalReports !== state.technicalReports) tasks.push(supabase.from('technical_reports').upsert(nextState.technicalReports));

      await Promise.all(tasks);
      setSyncStatus('synced');
    } catch (err: any) {
      setSyncStatus('error');
      addLog('فشل حفظ البيانات سحابياً', err.message, 'error');
    } finally {
      setTimeout(() => { isInternalUpdate.current = false; }, 1000);
    }
  }, [state, addLog]);

  useEffect(() => {
    if (!state.currentUser) return;
    fetchData();
    const channels = ['people', 'matches', 'categories'].map(t => 
        supabase.channel(`${t}-realtime`).on('postgres_changes', { event: '*', schema: 'public', table: t }, () => {
            if (!isInternalUpdate.current) fetchData();
        }).subscribe()
    );
    return () => { channels.forEach(c => supabase.removeChannel(c)); };
  }, [state.currentUser, fetchData]);

  const onLoginAttempt = async (u: string, p: string) => {
    // 1. Check Hardcoded Root Admin (Always works as fallback)
    if ((u === 'عزت' || u.toUpperCase() === 'IZZAT') && p === '123') {
        const user: AppUser = { id: 'root', username: 'عزت عامر الشيخة', role: 'مدير' };
        setState(prev => ({ ...prev, currentUser: user }));
        return user;
    }

    // 2. Check Database for other users
    try {
      const { data, error } = await supabase
        .from('app_users')
        .select('*')
        .eq('username', u)
        .eq('password', p)
        .maybeSingle();

      if (error) {
        throw new Error("حدث خطأ أثناء الاتصال بقاعدة البيانات.");
      }

      if (data) {
        const user: AppUser = data;
        setState(prev => ({ ...prev, currentUser: user }));
        return user;
      } else {
        throw new Error("اسم المستخدم أو كلمة المرور غير صحيحة.");
      }
    } catch (e: any) {
      throw e;
    }
  };

  if (!state.currentUser) return <Login onLoginAttempt={onLoginAttempt} />;

  const navItems = [
    { id: 'dashboard', label: 'الرئيسية', icon: LayoutDashboard },
    { id: 'squad', label: 'الفريق', icon: Users },
    { id: 'attendance', label: 'الحضور', icon: ClipboardCheck },
    { id: 'training', label: 'التدريبات', icon: Calendar },
    { id: 'matches', label: 'المباريات', icon: Trophy },
    { id: 'warehouse', label: 'المستودع', icon: Package },
    { id: 'reports', label: 'التقارير الفنية', icon: FilePieChart },
    { id: 'ai', label: 'المحلل الذكي', icon: Sparkles },
    { id: 'settings', label: 'الإعدادات', icon: Settings },
  ];

  const getSuspensionStatus = (personId: string, category: string) => {
    const personMatches = state.matches.filter(m => m.category === category && m.isCompleted);
    let currentYellows = 0;
    let hasActiveRed = false;

    personMatches.forEach(m => {
      const yellows = m.events.filter(e => e.type === 'yellow' && e.player === personId).length;
      const reds = m.events.filter(e => e.type === 'red' && e.player === personId).length;
      currentYellows += yellows;
      if (reds > 0) hasActiveRed = true;
    });

    return { 
      isSuspended: hasActiveRed || currentYellows >= 3,
      currentYellows,
      hasActiveRed
    };
  };

  return (
    <div className="min-h-screen bg-[#000F21] text-white font-['Tajawal']" dir="rtl">
      {/* Sidebar - Desktop */}
      <aside className={`fixed inset-y-0 right-0 z-50 w-72 bg-[#001F3F] border-l-4 border-orange-600 transition-transform duration-300 lg:translate-x-0 ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full'} no-print`}>
        <div className="flex flex-col h-full p-6">
          <div className="flex items-center gap-4 mb-10">
            <div className="bg-white p-2 rounded-2xl shadow-xl border-2 border-orange-600">
              <ClubLogo size={50} />
            </div>
            <div>
              <h2 className="text-xl font-black text-white">نادي الكرامة</h2>
              <p className="text-[10px] text-orange-400 font-bold uppercase tracking-widest">مكتب كرة القدم</p>
            </div>
          </div>

          <nav className="flex-1 space-y-2 overflow-y-auto custom-scrollbar">
            {navItems.map((item) => (
              <button
                key={item.id}
                onClick={() => { setActiveTab(item.id); setSidebarOpen(false); }}
                className={`w-full flex items-center gap-4 px-6 py-4 rounded-2xl font-black text-sm transition-all border-2 ${
                  activeTab === item.id 
                    ? 'bg-orange-600 border-white text-white shadow-lg translate-x-[-8px]' 
                    : 'bg-[#000F21]/30 border-transparent text-slate-400 hover:bg-white/5 hover:text-white'
                }`}
              >
                <item.icon size={22} />
                {item.label}
              </button>
            ))}
          </nav>

          <div className="pt-6 border-t border-white/10 mt-6 space-y-4">
             <div className="flex items-center gap-3 px-4 py-2 bg-black/20 rounded-xl">
                <div className="w-10 h-10 bg-orange-600 rounded-full flex items-center justify-center font-black text-white border-2 border-white shadow-inner">
                   {state.currentUser.username.charAt(0)}
                </div>
                <div>
                   <p className="text-xs font-black">{state.currentUser.username}</p>
                   <p className="text-[9px] text-orange-400 font-bold uppercase">{state.currentUser.role}</p>
                </div>
             </div>
             <button 
              onClick={() => setState(prev => ({ ...prev, currentUser: null }))}
              className="w-full flex items-center gap-4 px-6 py-4 rounded-2xl font-black text-sm text-red-400 hover:bg-red-400/10 transition-all"
             >
               <LogOut size={22} />
               تسجيل الخروج
             </button>
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="lg:pr-72 transition-all min-h-screen">
        <header className="sticky top-0 z-40 bg-[#000F21]/80 backdrop-blur-xl border-b-2 border-white/10 px-6 py-4 flex items-center justify-between no-print">
          <div className="flex items-center gap-4">
             <button onClick={() => setSidebarOpen(true)} className="lg:hidden p-3 bg-white/5 rounded-xl text-white">
                <Menu size={24} />
             </button>
             <h1 className="text-xl md:text-2xl font-black text-white drop-shadow-md">
                {navItems.find(i => i.id === activeTab)?.label}
             </h1>
          </div>

          <div className="flex items-center gap-4">
             <div className="hidden md:flex flex-col items-end">
                <div className="flex items-center gap-2">
                   {syncStatus === 'syncing' ? <RefreshCw size={14} className="animate-spin text-orange-400"/> : <CloudCheck size={16} className="text-emerald-400"/>}
                   <span className="text-[10px] font-black uppercase tracking-widest">{syncStatus === 'syncing' ? 'جاري المزامنة...' : 'قاعدة البيانات متصلة'}</span>
                </div>
                <p className="text-[9px] text-slate-500 font-bold">آخر تحديث: {new Date().toLocaleTimeString('ar-SY')}</p>
             </div>
             <div className="bg-white/5 p-3 rounded-xl border border-white/10 relative group cursor-pointer hover:bg-white/10 transition-all">
                <Bell size={20} />
                {state.notifications.some(n => !n.isRead) && (
                  <span className="absolute top-2 right-2 w-2.5 h-2.5 bg-orange-600 rounded-full border-2 border-[#000F21]"></span>
                )}
             </div>
          </div>
        </header>

        <div className="p-6 md:p-10 max-w-7xl mx-auto">
          {activeTab === 'dashboard' && <Dashboard state={state} setState={setState} onMatchClick={(id) => { setSelectedMatchId(id); setActiveTab('matches'); }} onSessionClick={() => setActiveTab('attendance')} onPlayerClick={(p) => { setSelectedPlayer(p); setActiveTab('player-report'); }} />}
          {activeTab === 'squad' && <SquadManagement state={state} setState={updateStateAndSync} onOpenReport={(p) => { setSelectedPlayer(p); setActiveTab('player-report'); }} addLog={addLog} getSuspension={getSuspensionStatus} />}
          {activeTab === 'attendance' && <AttendanceTracker state={state} setState={setState} addLog={addLog} />}
          {activeTab === 'training' && <TrainingPlanner state={state} setState={setState} addLog={addLog} />}
          {activeTab === 'matches' && <MatchPlanner state={state} setState={setState} addLog={addLog} getSuspension={getSuspensionStatus} />}
          {activeTab === 'warehouse' && <WarehouseManagement state={state} setState={updateStateAndSync} addLog={addLog} />}
          {activeTab === 'reports' && <TechnicalReports state={state} setState={updateStateAndSync} addLog={addLog} />}
          {activeTab === 'ai' && <AIAssistant state={state} />}
          {activeTab === 'settings' && <SettingsView state={state} setState={setState} addLog={addLog} />}
          {activeTab === 'player-report' && <PlayerReport state={state} player={selectedPlayer} onBack={() => setActiveTab('squad')} />}
        </div>

        <ChatBot state={state} />
      </main>

      {/* Sidebar Overlay - Mobile */}
      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/60 backdrop-blur-sm z-40 lg:hidden no-print"
          onClick={() => setSidebarOpen(false)}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Lock, User, Eye, EyeOff, ChevronLeft, Loader2, Sparkles, CheckCircle2 } from 'lucide-react';
import { AppUser } from '../types';
import ClubLogo from './ClubLogo';

interface LoginProps {
  onLoginAttempt: (username: string, password: string) => Promise<AppUser | null>;
}

const Login: React.FC<LoginProps> = ({ onLoginAttempt }) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [showPass, setShowPass] = useState(false);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [loginSuccess, setLoginSuccess] = useState(false);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!username.trim() || !password) {
      setError('يرجى إدخال اسم المستخدم وكلمة المرور.');
      return;
    }

    setLoading(true);
    setError('');

    try {
      const user = await onLoginAttempt(username, password);
      if (user) {
        setLoginSuccess(true);
      }
    } catch (err: any) {
      // عرض الرسالة المحددة القادمة من الاستعلام (مثلاً: كلمة المرور خاطئة)
      setError(err.message || 'فشل تسجيل الدخول. يرجى المحاولة لاحقاً.');
      setLoading(false);
    }
  };

  if (loginSuccess) {
    return (
      <div className="min-h-screen bg-[#001F3F] flex flex-col items-center justify-center p-6 font-['Tajawal'] relative overflow-hidden" dir="rtl">
        <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')] opacity-20"></div>
        <div className="relative z-10 flex flex-col items-center animate-in zoom-in duration-700">
          <div className="relative">
             <div className="absolute inset-0 bg-orange-500 rounded-full blur-3xl opacity-20 animate-pulse"></div>
             <div className="bg-white p-10 rounded-full shadow-[0_0_100px_rgba(255,107,0,0.4)] border-8 border-orange-500/20 animate-bounce">
                <ClubLogo size={180} />
             </div>
             <div className="absolute -top-4 -right-4 bg-emerald-500 text-white p-4 rounded-full shadow-2xl animate-in slide-in-from-bottom-4 duration-500">
                <CheckCircle2 size={48} />
             </div>
          </div>
          <h2 className="text-white text-5xl font-black mt-12 tracking-tighter animate-in fade-in slide-in-from-bottom-8 duration-1000">تم التأكيد بنجاح</h2>
          <p className="text-orange-400 text-xl font-bold mt-4 opacity-80 uppercase tracking-widest animate-pulse">جاري فتح غرفة العمليات المركزية...</p>
          <div className="mt-12 flex gap-2">
             <div className="w-3 h-3 bg-white rounded-full animate-bounce [animation-delay:-0.3s]"></div>
             <div className="w-3 h-3 bg-white rounded-full animate-bounce [animation-delay:-0.15s]"></div>
             <div className="w-3 h-3 bg-white rounded-full animate-bounce"></div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#001F3F] flex flex-col items-center justify-center p-6 font-['Tajawal'] relative overflow-hidden" dir="rtl">
      {/* Decorative Elements */}
      <div className="absolute top-[-15%] right-[-10%] w-[50%] h-[50%] bg-orange-600/10 rounded-full blur-[120px]"></div>
      <div className="absolute bottom-[-15%] left-[-10%] w-[40%] h-[40%] bg-blue-600/10 rounded-full blur-[100px]"></div>

      <div className="max-w-md w-full bg-white rounded-[4rem] shadow-[0_32px_64px_-12px_rgba(0,0,0,0.5)] overflow-hidden border border-white/20 animate-in fade-in zoom-in-95 duration-700 relative z-10">
        <div className="bg-gradient-to-br from-[#001F3F] to-[#000F21] p-12 flex flex-col items-center text-center">
          <div className="bg-white p-6 rounded-[3rem] shadow-2xl mb-8 ring-8 ring-orange-500/10 transition-transform hover:scale-105 duration-500">
            <ClubLogo size={120} />
          </div>
          <h2 className="text-white font-black text-2xl tracking-tight leading-snug uppercase">AL-Karamah Sport Club</h2>
          <h2 className="text-white font-black text-xl tracking-tight leading-snug mt-2">نادي الكرامة الرياضي - مكتب كرة القدم</h2>
          <p className="text-orange-400 font-black mt-5 text-sm uppercase tracking-widest bg-orange-500/10 px-6 py-2 rounded-full border border-orange-500/20">أهلاً بك في عائلة الكرامة الأسيوي</p>
        </div>

        <div className="p-12 space-y-8">
          <form onSubmit={handleLogin} className="space-y-8">
            {error && (
              <div className="bg-red-50 text-red-600 p-4 rounded-2xl text-[12px] font-black text-center border-2 border-red-200 animate-bounce">
                {error}
              </div>
            )}

            <div className="space-y-3">
              <label className="text-[11px] font-black text-slate-500 mr-2 uppercase flex items-center gap-2">
                <User size={14} className="text-[#001F3F]" /> اسم المستخدم
              </label>
              <input 
                type="text" 
                value={username} 
                onChange={e => setUsername(e.target.value)}
                disabled={loading}
                placeholder="" 
                className="w-full bg-slate-50 border-2 border-slate-100 rounded-3xl py-5 px-8 outline-none focus:ring-4 focus:ring-orange-500/10 focus:border-orange-500 font-black text-slate-800 transition-all text-xl disabled:opacity-50" 
              />
            </div>

            <div className="space-y-3">
              <label className="text-[11px] font-black text-slate-500 mr-2 uppercase flex items-center gap-2">
                <Lock size={14} className="text-[#001F3F]" /> كلمة المرور
              </label>
              <div className="relative">
                <input 
                  type={showPass ? "text" : "password"} 
                  value={password} 
                  onChange={e => setPassword(e.target.value)}
                  disabled={loading}
                  placeholder=""
                  className="w-full bg-slate-50 border-2 border-slate-100 rounded-3xl py-5 pr-8 pl-16 outline-none focus:ring-4 focus:ring-orange-500/10 focus:border-orange-500 font-black text-slate-800 transition-all text-xl disabled:opacity-50" 
                />
                <button 
                  type="button" 
                  onClick={() => setShowPass(!showPass)} 
                  className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 hover:text-orange-600 transition-colors p-3"
                >
                  {showPass ? <EyeOff size={24} /> : <Eye size={24} />}
                </button>
              </div>
            </div>

            <button 
              type="submit" 
              disabled={loading}
              className="w-full bg-[#001F3F] text-white font-black py-6 rounded-[2.5rem] hover:bg-black transition-all shadow-2xl shadow-blue-900/40 mt-4 text-2xl flex items-center justify-center gap-4 group disabled:opacity-70 overflow-hidden relative"
            >
              {loading ? (
                <>
                  <Loader2 className="animate-spin" size={28} />
                  جاري التحقق...
                </>
              ) : (
                <>
                  دخول آمن
                  <ChevronLeft className="group-hover:-translate-x-2 transition-transform" size={28} />
                </>
              )}
            </button>
          </form>

          <div className="pt-8 border-t border-slate-100 text-center space-y-2">
            <p className="text-[10px] text-slate-500 font-black uppercase tracking-[0.2em]">Football Management Pro System</p>
            <p className="text-[10px] text-slate-400 font-bold">نادي الكرامة | نسخة مكتب كرة القدم</p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Login;

import React, { useState, useMemo } from 'react';
import { FilePieChart, Star, Search, Filter, Plus, User, Trophy, Calendar, CheckCircle, Save, X, Loader2, Sparkles, TrendingUp, Activity, ShieldAlert } from 'lucide-react';
import { AppState, TechnicalReport, Category, Match, Person } from '../types';
import { generateUUID } from '../App';

interface TechnicalReportsProps {
  state: AppState;
  setState: (updater: (prev: AppState) => AppState) => void;
  addLog?: (m: string, d?: string, t?: any) => void;
}

const TechnicalReports: React.FC<TechnicalReportsProps> = ({ state, setState, addLog }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [activeReportType, setActiveReportType] = useState<'match_evaluation' | 'staff_review'>('match_evaluation');
