        .custom-scrollbar::-webkit-scrollbar-thumb { background: #FF6B00; border-radius: 10px; }
        input, select, textarea { text-shadow: none !important; color: white !important; background: #001F3F !important; }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { 
  Users, Calendar, ClipboardCheck, LayoutDashboard, Settings, LogOut, Menu, X, Trophy, RefreshCw, CloudCheck, Sparkles, Package, FilePieChart, Printer, Loader2
} from 'lucide-react';
import { createClient } from '@supabase/supabase-js';
import { AppUser, AppState, Person } from './types';
import html2pdf from 'html2pdf.js';

// استيراد المكونات
import Dashboard from './components/Dashboard';
import SquadManagement from './components/SquadManagement';
import AttendanceTracker from './components/AttendanceTracker';
import TrainingPlanner from './components/TrainingPlanner';
import MatchPlanner from './components/MatchPlanner';
import SettingsView from './components/SettingsView';
import PlayerReport from './components/PlayerReport';
import WarehouseManagement from './components/WarehouseManagement';
import Login from './components/Login';
import ClubLogo from './components/ClubLogo';
import AIAssistant from './components/AIAssistant';
import ChatBot from './components/ChatBot';
import TechnicalReports from './components/TechnicalReports';

// --- Global Utilities ---
export const generateUUID = () => {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) return crypto.randomUUID();
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = Math.random() * 16 | 0, v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
};

// --- Supabase Config ---
const supabaseUrl = 'https://kfwqoigsghlgigjriyxf.supabase.co';
const supabaseAnonKey = 'sb_publishable_O2vR2yKUG-FVeaydD4z6Lg_tjFcKDic';
export const supabase = createClient(supabaseUrl, supabaseAnonKey);

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isSidebarOpen, setSidebarOpen] = useState(true);
  const [syncStatus, setSyncStatus] = useState<'synced' | 'error' | 'syncing'>('synced');
  const [isInitialLoading, setIsInitialLoading] = useState(false);
  const [selectedPlayer, setSelectedPlayer] = useState<Person | null>(null);
  const [selectedMatchId, setSelectedMatchId] = useState<string | null>(null);

  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('alkarama_secure_v10');
    if (saved) { try { return JSON.parse(saved); } catch (e) { return {} as AppState; } }
    return {
      currentUser: null, categories: ['الرجال', 'الشباب', 'الناشئين', 'الأشبال'],
      people: [], sessions: [], matches: [], warehouse: [], technicalReports: [],
      attendance: [], users: [], notifications: [], globalCategoryFilter: 'الكل'
    };
  });

  // دالة لجلب كافة البيانات من السحابة
  const fetchAllData = useCallback(async (user: AppUser) => {
    setIsInitialLoading(true);
    setSyncStatus('syncing');
    try {
      const [ppl, mtch, attn, wrhs, tech, usrs, cats, sess] = await Promise.all([
        supabase.from('people').select('*'),
        supabase.from('matches').select('*'),
        supabase.from('attendance').select('*'),
        supabase.from('warehouse').select('*'),
        supabase.from('technical_reports').select('*'),
        supabase.from('app_users').select('*'),
        supabase.from('categories').select('*'),
        supabase.from('sessions').select('*')
      ]);

      setState(prev => ({
        ...prev,
        currentUser: user,
        people: ppl.data || [],
        matches: mtch.data || [],
        attendance: attn.data || [],
        warehouse: wrhs.data || [],
        technicalReports: tech.data || [],
        users: usrs.data || [],
        categories: cats.data?.map(c => c.name) || prev.categories,
        sessions: sess.data || []
      }));
      setSyncStatus('synced');
    } catch (e) {
      console.error("Data Fetch Error:", e);
      setSyncStatus('error');
    } finally {
      setIsInitialLoading(false);
    }
  }, []);

  // المزامنة التلقائية عند الدخول
  useEffect(() => {
    if (state.currentUser && state.people.length === 0) {
      fetchAllData(state.currentUser);
    }
  }, [state.currentUser, fetchAllData, state.people.length]);

  const handleExportPDF = (elementId: string, title: string) => {
    const element = document.getElementById(elementId);
    if (!element) return;
    // Fix: Changed margin from [10, 10] to 10 to resolve TypeScript tuple assignment error.
    // The Html2PdfOptions type expects a number or a fixed-size tuple, and [10, 10] was being inferred as number[].
    const opt = {
      margin: 10,
      filename: `نادي_الكرامة_${title}.pdf`,
      image: { type: 'jpeg', quality: 1 },
      html2canvas: { scale: 2, useCORS: true, backgroundColor: "#ffffff" },
      jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
    };
    element.classList.add('official-pdf-mode');
    html2pdf().set(opt).from(element).save().then(() => {
      element.classList.remove('official-pdf-mode');
    });
  };

  const updateStateAndSync = async (updater: (prev: AppState) => AppState) => {
    const nextState = updater(state);
    setState(nextState);
    localStorage.setItem('alkarama_secure_v10', JSON.stringify(nextState));

    if (!nextState.currentUser) return;
    setSyncStatus('syncing');

    try {
      // مزامنة كافة الجداول بما فيها المستخدمين والفئات لضمان عمل الحسابات الجديدة
      await Promise.all([
        supabase.from('people').upsert(nextState.people),
        supabase.from('matches').upsert(nextState.matches),
        supabase.from('attendance').upsert(nextState.attendance),
        supabase.from('warehouse').upsert(nextState.warehouse),
        supabase.from('technical_reports').upsert(nextState.technicalReports),
        supabase.from('app_users').upsert(nextState.users),
        supabase.from('sessions').upsert(nextState.sessions),
        supabase.from('categories').upsert(nextState.categories.map(c => ({ name: c })), { onConflict: 'name' })
      ]);
      setSyncStatus('synced');
    } catch (e) {
      console.error("Sync Error:", e);
      setSyncStatus('error');
    }
  };

  const onLoginAttempt = async (u: string, p: string) => {
    // 1. الدخول بالحساب الرئيسي (عزت)
    if ((u === 'عزت' || u.toUpperCase() === 'IZZAT') && p === '123') {
      const user: AppUser = { id: 'root', username: 'عزت عامر الشيخة', role: 'مدير' };
      await fetchAllData(user);
      return user;
    }

    // 2. التحقق من قاعدة البيانات للحسابات الأخرى
    try {
      const { data, error } = await supabase
        .from('app_users')
        .select('*')
        .eq('username', u)
        .eq('password', p)
        .maybeSingle();

      if (error) throw new Error("فشل الاتصال بخادم النادي");
      if (!data) throw new Error("بيانات الدخول غير صحيحة");

      const user: AppUser = data;
      await fetchAllData(user);
      return user;
    } catch (e: any) {
      throw e;
    }
  };

  if (!state.currentUser) return (
    <div className="min-h-screen bg-[#000F21] flex flex-col items-center justify-center p-6">
       <ClubLogo size={120} className="mb-8" />
       <Login onLoginAttempt={onLoginAttempt} />
    </div>
  );

  // واجهة التحميل الأولية عند جلب البيانات
  if (isInitialLoading) {
    return (
      <div className="min-h-screen bg-[#000F21] flex flex-col items-center justify-center p-6 text-white font-['Tajawal']" dir="rtl">
         <div className="animate-bounce mb-8">
            <ClubLogo size={150} />
         </div>
         <Loader2 className="animate-spin text-orange-500 mb-4" size={48} />
         <h2 className="text-2xl font-black mb-2">جاري مزامنة بيانات النادي...</h2>
         <p className="text-orange-400 font-bold opacity-70 animate-pulse uppercase tracking-[0.2em]">جلب سجلات اللاعبين والكوادر والنتائج</p>
      </div>
    );
  }

  const navItems = [
    { id: 'dashboard', label: 'الرئيسية', icon: LayoutDashboard },
    { id: 'squad', label: 'الفريق', icon: Users },
    { id: 'attendance', label: 'الحضور', icon: ClipboardCheck },
    { id: 'training', label: 'التدريبات', icon: Calendar },
    { id: 'matches', label: 'المباريات', icon: Trophy },
    { id: 'tech_reports', label: 'التقارير', icon: FilePieChart },
    { id: 'warehouse', label: 'المخزن', icon: Package },
    { id: 'ai', label: 'الذكاء الفني', icon: Sparkles },
    { id: 'settings', label: 'الإعدادات', icon: Settings },
  ];

  const getSuspensionStatus = (personId: string, category: string) => {
    const personMatches = state.matches.filter(m => m.category === category && m.isCompleted);
    let currentYellows = 0;
    let hasActiveRed = false;
    personMatches.forEach(m => {
      currentYellows += m.events.filter(e => e.type === 'yellow' && e.player === personId).length;
      if (m.events.filter(e => e.type === 'red' && e.player === personId).length > 0) hasActiveRed = true;
    });
    return { isSuspended: hasActiveRed || currentYellows >= 3, currentYellows, hasActiveRed };
  };

  return (
    <div className="flex h-screen bg-[#000F21] text-white font-['Tajawal'] dir-rtl" dir="rtl">
      {/* القائمة الجانبية */}
      <aside className={`bg-[#001F3F] border-l border-[#FF6B00] transition-all duration-300 flex flex-col z-50 shadow-2xl
        ${isSidebarOpen ? 'w-64' : 'w-0 lg:w-20 overflow-hidden'}`}>
        <div className="p-6 flex flex-col items-center border-b border-white/5 bg-[#00172F]">
           <ClubLogo size={isSidebarOpen ? 80 : 40} />
           {isSidebarOpen && <span className="mt-3 font-black text-white text-lg tracking-wider">نادي الكرامة</span>}
        </div>
        <nav className="flex-1 p-3 space-y-2 overflow-y-auto custom-scrollbar">
          {navItems.map(item => (
            <button key={item.id} onClick={() => setActiveTab(item.id)}
              className={`w-full flex items-center gap-4 px-4 py-4 rounded-xl font-bold transition-all
              ${activeTab === item.id ? 'bg-[#FF6B00] text-white shadow-lg' : 'hover:bg-white/10 text-white/50 hover:text-white'}`}>
              <item.icon size={22} />
              {isSidebarOpen && <span className="text-sm whitespace-nowrap">{item.label}</span>}
            </button>
          ))}
        </nav>
        <button onClick={() => setState(prev => ({ ...prev, currentUser: null }))}
          className="m-4 flex items-center gap-3 p-4 rounded-xl text-red-400 hover:bg-red-500/10 border border-red-500/20 font-bold transition-all">
          <LogOut size={20} />
          {isSidebarOpen && <span>خروج</span>}
        </button>
      </aside>

      {/* المحتوى الرئيسي */}
      <main className="flex-1 flex flex-col overflow-hidden relative">
        <header className="bg-[#001F3F] border-b border-[#FF6B00] px-6 py-4 flex items-center justify-between shadow-xl z-40">
          <div className="flex items-center gap-4">
             <button onClick={() => setSidebarOpen(!isSidebarOpen)} className="p-2 bg-white/5 rounded-lg text-white hover:text-[#FF6B00]">
               {isSidebarOpen ? <X /> : <Menu />}
             </button>
             <h1 className="text-xl font-black">{navItems.find(n => n.id === activeTab)?.label}</h1>
          </div>
          <div className="flex items-center gap-4">
             <div className={`flex items-center gap-2 px-3 py-1.5 rounded-full border ${syncStatus === 'synced' ? 'border-green-500 text-green-400' : 'border-orange-500 text-orange-400'}`}>
                {syncStatus === 'synced' ? <CloudCheck size={16} /> : <RefreshCw size={16} className="animate-spin" />}
                <span className="text-[11px] font-bold tracking-widest uppercase">{syncStatus}</span>
             </div>
             <button onClick={() => handleExportPDF('main-content', activeTab)} 
               className="bg-white text-[#001F3F] px-4 py-2 rounded-xl font-black text-sm hover:bg-[#FF6B00] hover:text-white transition-all shadow-xl flex items-center gap-2">
                <Printer size={18} /> تصدير PDF
             </button>
          </div>
        </header>

        <section className="flex-1 overflow-y-auto p-6 custom-scrollbar bg-[#000F21]">
          <div id="main-content" className="max-w-7xl mx-auto min-h-full">
            <div className="main-render-area">
              {activeTab === 'dashboard' && <Dashboard state={state} setState={updateStateAndSync as any} onMatchClick={(id) => { setSelectedMatchId(id); setActiveTab('matches'); }} onSessionClick={() => setActiveTab('attendance')} />}
              {activeTab === 'squad' && <SquadManagement state={state} setState={updateStateAndSync as any} onOpenReport={p => { setSelectedPlayer(p); setActiveTab('report'); }} addLog={() => {}} getSuspension={getSuspensionStatus} />}
              {activeTab === 'attendance' && <AttendanceTracker state={state} setState={updateStateAndSync as any} addLog={() => {}} />}
              {activeTab === 'training' && <TrainingPlanner state={state} setState={updateStateAndSync as any} addLog={() => {}} />}
              {activeTab === 'matches' && <MatchPlanner state={state} setState={updateStateAndSync as any} defaultSelectedId={selectedMatchId} addLog={() => {}} getSuspension={getSuspensionStatus} />}
              {activeTab === 'tech_reports' && <TechnicalReports state={state} setState={updateStateAndSync as any} addLog={() => {}} />}
              {activeTab === 'warehouse' && <WarehouseManagement state={state} setState={updateStateAndSync as any} addLog={() => {}} />}
              {activeTab === 'ai' && <AIAssistant state={state} />}
              {activeTab === 'settings' && <SettingsView state={state} setState={updateStateAndSync as any} addLog={() => {}} />}
              {activeTab === 'report' && <PlayerReport player={selectedPlayer} state={state} onBack={() => setActiveTab('squad')} />}
            </div>
          </div>
        </section>
      </main>
      <ChatBot state={state} />
      <style>{`
        * { text-shadow: 1px 1px 3px rgba(0, 0, 0, 0.8) !important; -webkit-font-smoothing: antialiased; }
        .official-pdf-mode { background: white !important; color: black !important; padding: 40px !important; }
        .custom-scrollbar::-webkit-scrollbar { width: 6px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #FF6B00; border-radius: 10px; }
        input, select, textarea { text-shadow: none !important; color: white !important; background: #001F3F !important; }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Lock, User, Eye, EyeOff, ChevronLeft, Loader2, Sparkles, CheckCircle2 } from 'lucide-react';
import { AppUser } from '../types';
import ClubLogo from './ClubLogo';

interface LoginProps {
  onLoginAttempt: (username: string, password: string) => Promise<AppUser | null>;
}

const Login: React.FC<LoginProps> = ({ onLoginAttempt }) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [showPass, setShowPass] = useState(false);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [loginSuccess, setLoginSuccess] = useState(false);

  // نمط خلفية برمجي بديل للصورة الخارجية
  const techPattern = {
    backgroundImage: `
      radial-gradient(circle at 2px 2px, rgba(255,255,255,0.05) 1px, transparent 0),
      linear-gradient(to right, rgba(255,255,255,0.02) 1px, transparent 1px),
      linear-gradient(to bottom, rgba(255,255,255,0.02) 1px, transparent 1px)
    `,
    backgroundSize: '24px 24px, 40px 40px, 40px 40px'
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!username.trim() || !password) {
      setError('يرجى إدخال اسم المستخدم وكلمة المرور.');
      return;
    }

    setLoading(true);
    setError('');

    try {
      const user = await onLoginAttempt(username, password);
      if (user) {
        setLoginSuccess(true);
      }
    } catch (err: any) {
      setError(err.message || 'فشل تسجيل الدخول. يرجى المحاولة لاحقاً.');
      setLoading(false);
    }
  };

  if (loginSuccess) {
    return (
      <div className="min-h-screen bg-[#001F3F] flex flex-col items-center justify-center p-6 font-['Tajawal'] relative overflow-hidden" dir="rtl" style={techPattern}>
        <div className="relative z-10 flex flex-col items-center animate-in zoom-in duration-700">
          <div className="relative">
             <div className="absolute inset-0 bg-orange-500 rounded-full blur-3xl opacity-20 animate-pulse"></div>
             <div className="bg-white p-10 rounded-full shadow-[0_0_100px_rgba(255,107,0,0.4)] border-8 border-orange-500/20 animate-bounce">
                <ClubLogo size={180} />
             </div>
             <div className="absolute -top-4 -right-4 bg-emerald-500 text-white p-4 rounded-full shadow-2xl animate-in slide-in-from-bottom-4 duration-500">
                <CheckCircle2 size={48} />
             </div>
          </div>
          <h2 className="text-white text-5xl font-black mt-12 tracking-tighter animate-in fade-in slide-in-from-bottom-8 duration-1000">تم التأكيد بنجاح</h2>
          <p className="text-orange-400 text-xl font-bold mt-4 opacity-80 uppercase tracking-widest animate-pulse">جاري فتح غرفة العمليات المركزية...</p>
          <div className="mt-12 flex gap-2">
             <div className="w-3 h-3 bg-white rounded-full animate-bounce [animation-delay:-0.3s]"></div>
             <div className="w-3 h-3 bg-white rounded-full animate-bounce [animation-delay:-0.15s]"></div>
             <div className="w-3 h-3 bg-white rounded-full animate-bounce"></div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#001F3F] flex flex-col items-center justify-center p-6 font-['Tajawal'] relative overflow-hidden" dir="rtl" style={techPattern}>
      {/* Decorative Elements */}
      <div className="absolute top-[-15%] right-[-10%] w-[50%] h-[50%] bg-orange-600/10 rounded-full blur-[120px]"></div>
      <div className="absolute bottom-[-15%] left-[-10%] w-[40%] h-[40%] bg-blue-600/10 rounded-full blur-[100px]"></div>

      <div className="max-w-md w-full bg-white rounded-[4rem] shadow-[0_32px_64px_-12px_rgba(0,0,0,0.5)] overflow-hidden border border-white/20 animate-in fade-in zoom-in-95 duration-700 relative z-10">
        <div className="bg-gradient-to-br from-[#001F3F] to-[#000F21] p-12 flex flex-col items-center text-center">
          <div className="bg-white p-6 rounded-[3rem] shadow-2xl mb-8 ring-8 ring-orange-500/10 transition-transform hover:scale-105 duration-500">
            <ClubLogo size={120} />
          </div>
          <h2 className="text-white font-black text-2xl tracking-tight leading-snug uppercase">AL-Karamah Sport Club</h2>
          <h2 className="text-white font-black text-xl tracking-tight leading-snug mt-2">نادي الكرامة الرياضي - مكتب كرة القدم</h2>
          <p className="text-orange-400 font-black mt-5 text-sm uppercase tracking-widest bg-orange-500/10 px-6 py-2 rounded-full border border-orange-500/20">أهلاً بك في عائلة الكرامة الأسيوي</p>
        </div>

        <div className="p-12 space-y-8">
          <form onSubmit={handleLogin} className="space-y-8">
            {error && (
              <div className="bg-red-50 text-red-600 p-4 rounded-2xl text-[12px] font-black text-center border-2 border-red-200 animate-bounce">
                {error}
              </div>
            )}

            <div className="space-y-3">
              <label className="text-[11px] font-black text-slate-500 mr-2 uppercase flex items-center gap-2">
                <User size={14} className="text-[#001F3F]" /> اسم المستخدم
              </label>
              <input 
                type="text" 
                value={username} 
                onChange={e => setUsername(e.target.value)}
                disabled={loading}
                placeholder="" 
                className="w-full bg-slate-50 border-2 border-slate-100 rounded-3xl py-5 px-8 outline-none focus:ring-4 focus:ring-orange-500/10 focus:border-orange-500 font-black text-slate-800 transition-all text-xl disabled:opacity-50" 
              />
            </div>

            <div className="space-y-3">
              <label className="text-[11px] font-black text-slate-500 mr-2 uppercase flex items-center gap-2">
                <Lock size={14} className="text-[#001F3F]" /> كلمة المرور
              </label>
              <div className="relative">
                <input 
                  type={showPass ? "text" : "password"} 
                  value={password} 
                  onChange={e => setPassword(e.target.value)}
                  disabled={loading}
                  placeholder=""
                  className="w-full bg-slate-50 border-2 border-slate-100 rounded-3xl py-5 pr-8 pl-16 outline-none focus:ring-4 focus:ring-orange-500/10 focus:border-orange-500 font-black text-slate-800 transition-all text-xl disabled:opacity-50" 
                />
                <button 
                  type="button" 
                  onClick={() => setShowPass(!showPass)} 
                  className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 hover:text-orange-600 transition-colors p-3"
                >
                  {showPass ? <EyeOff size={24} /> : <Eye size={24} />}
                </button>
              </div>
            </div>

            <button 
              type="submit" 
              disabled={loading}
              className="w-full bg-[#001F3F] text-white font-black py-6 rounded-[2.5rem] hover:bg-black transition-all shadow-2xl shadow-blue-900/40 mt-4 text-2xl flex items-center justify-center gap-4 group disabled:opacity-70 overflow-hidden relative"
            >
              {loading ? (
                <>
                  <Loader2 className="animate-spin" size={28} />
                  جاري التحقق...
                </>
              ) : (
                <>
                  دخول آمن
                  <ChevronLeft className="group-hover:-translate-x-2 transition-transform" size={28} />
                </>
              )}
            </button>
          </form>

          <div className="pt-8 border-t border-slate-100 text-center space-y-2">
            <p className="text-[10px] text-slate-500 font-black uppercase tracking-[0.2em]">Football Management Pro System</p>
            <p className="text-[10px] text-slate-400 font-bold">نادي الكرامة | نسخة مكتب كرة القدم</p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Login;

