    };
  });

  // دالة جلب كافة البيانات من السحابة
  const fetchAllData = useCallback(async (user: AppUser) => {
    setIsInitialLoading(true);
    setSyncStatus('syncing');
    try {
      const [ppl, mtch, attn, wrhs, tech, usrs, sess, cats] = await Promise.all([
        supabase.from('people').select('*'),
        supabase.from('matches').select('*'),
        supabase.from('attendance').select('*'),
        supabase.from('warehouse').select('*'),
        supabase.from('technical_reports').select('*'),
        supabase.from('app_users').select('*'),
        supabase.from('sessions').select('*'),
        supabase.from('categories').select('*') // جلب الفئات من السحابة
      ]);

      setState(prev => ({
        ...prev,
        currentUser: user,
        people: ppl.data || [],
        matches: mtch.data || [],
        attendance: attn.data || [],
        warehouse: wrhs.data || [],
        technicalReports: tech.data || [],
        users: usrs.data || [],
        sessions: sess.data || [],
        categories: cats.data && cats.data.length > 0 ? cats.data.map(c => c.name) : prev.categories
      }));
      setSyncStatus('synced');
    } catch (e) {
      console.error("Fetch Error:", e);
      setSyncStatus('error');
    } finally {
      setIsInitialLoading(false);
    }
  }, []);

  // --- نظام المزامنة اللحظية (Real-time Channels) ---
  useEffect(() => {
    if (!state.currentUser) return;

    const channels = [
      'people', 'matches', 'sessions', 'attendance', 'warehouse', 'technical_reports', 'categories'
    ].map(table => {
      return supabase
        .channel(`public:${table}`)
        .on('postgres_changes', { event: '*', schema: 'public', table }, (payload) => {
          setSyncStatus('syncing');

          setState(prev => {
            if (table === 'categories') {
                // معالجة خاصة لجدول الفئات لأنه مصفوفة نصوص في الـ State
                const currentCats = [...prev.categories];
                if (payload.eventType === 'INSERT' && !currentCats.includes(payload.new.name)) {
                    return { ...prev, categories: [...currentCats, payload.new.name] };
                }
                return prev;
            }

            const currentTableData = (prev as any)[table] || [];
            let nextTableData = [...currentTableData];

            if (payload.eventType === 'INSERT') {
              if (!nextTableData.find(item => item.id === payload.new.id)) {
                nextTableData = [payload.new, ...nextTableData];
              }
            } else if (payload.eventType === 'UPDATE') {
              nextTableData = nextTableData.map(item => item.id === payload.new.id ? payload.new : item);
            } else if (payload.eventType === 'DELETE') {
              nextTableData = nextTableData.filter(item => item.id === payload.old.id);
            }

            return { ...prev, [table]: nextTableData };
          });

          setTimeout(() => setSyncStatus('synced'), 1000);
        })
        .subscribe();
    });

    return () => {
      channels.forEach(channel => supabase.removeChannel(channel));
    };
  }, [state.currentUser]);

  const handleExportPDF = (elementId: string, title: string) => {
