import React, { useState, useRef } from 'react';
import { AppState, TacticalPlan } from '../types';
import { generateUUID } from '../App';
import { Save, Trash2, Plus, Users, Layout, Map as MapIcon, ChevronRight } from 'lucide-react';

interface TacticalBoardProps {
  state: AppState;
  setState: (updater: (prev: AppState) => AppState) => void;
}

const TacticalBoard: React.FC<TacticalBoardProps> = ({ state, setState }) => {
  const [selectedPlanId, setSelectedPlanId] = useState<string | null>(null);
  const [draggedPlayerId, setDraggedPlayerId] = useState<string | null>(null);
  const [currentFormation, setCurrentFormation] = useState('4-4-2');
  const boardRef = useRef<HTMLDivElement>(null);

  const activePlan = state.tacticalPlans.find(p => p.id === selectedPlanId);
  const players = state.people.filter(p => p.role === 'لاعب' && (state.globalCategoryFilter === 'الكل' || p.category === state.globalCategoryFilter));

  const handleDrop = (e: React.DragEvent) => {
    if (!draggedPlayerId || !boardRef.current || !selectedPlanId) return;
    const rect = boardRef.current.getBoundingClientRect();
    const x = ((e.clientX - rect.left) / rect.width) * 100;
    const y = ((e.clientY - rect.top) / rect.height) * 100;

    setState(prev => ({
      ...prev,
      tacticalPlans: prev.tacticalPlans.map(plan => {
        if (plan.id === selectedPlanId) {
          const newPositions = plan.positions.filter(pos => pos.playerId !== draggedPlayerId);
          newPositions.push({ playerId: draggedPlayerId, x, y });
          return { ...plan, positions: newPositions };
        }
        return plan;
      })
    }));
    setDraggedPlayerId(null);
  };

  const createNewPlan = () => {
    const newPlan: TacticalPlan = {
      id: generateUUID(),
      name: `خطة جديدة - ${new Date().toLocaleDateString('ar')}`,
      category: state.globalCategoryFilter === 'الكل' ? state.categories[0] : state.globalCategoryFilter,
      formation: currentFormation,
      positions: [],
      notes: ''
    };
    setState(prev => ({ ...prev, tacticalPlans: [newPlan, ...prev.tacticalPlans] }));
    setSelectedPlanId(newPlan.id);
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
        {/* قائمة الخطط */}
        <div className="lg:col-span-1 bg-[#001F3F] p-6 rounded-[2rem] border-2 border-[#FF6B00] shadow-xl">
           <h3 className="font-black text-xl mb-6 flex items-center gap-2">
             <Layout size={24} className="text-orange-500" /> مسودة الخطط
           </h3>
           <button onClick={createNewPlan} className="w-full bg-[#FF6B00] text-white py-3 rounded-xl font-black flex items-center justify-center gap-2 mb-6 shadow-lg">
             <Plus size={20}/> خطة جديدة
           </button>
           <div className="space-y-3 max-h-[400px] overflow-y-auto custom-scrollbar">
              {state.tacticalPlans.map(plan => (
                <button key={plan.id} onClick={() => setSelectedPlanId(plan.id)}
                  className={`w-full text-right p-4 rounded-xl border-2 transition-all font-bold ${selectedPlanId === plan.id ? 'border-orange-500 bg-orange-500/10' : 'border-white/10 hover:bg-white/5'}`}>
                   {plan.name}
                   <p className="text-[10px] opacity-50 mt-1">{plan.category}</p>
                </button>
              ))}
           </div>
        </div>

        {/* الملعب التكتيكي */}
        <div className="lg:col-span-3">
          {activePlan ? (
            <div className="bg-[#001F3F] p-8 rounded-[3rem] border-2 border-white/20 shadow-2xl">
               <div className="flex justify-between items-center mb-6">
                  <input value={activePlan.name} onChange={e => {
                    const val = e.target.value;
                    setState(p => ({...p, tacticalPlans: p.tacticalPlans.map(tp => tp.id === activePlan.id ? {...tp, name: val} : tp)}));
                  }} className="bg-transparent text-2xl font-black outline-none border-b-2 border-orange-500 pb-1" />
                  <button onClick={() => setState(p => ({...p, tacticalPlans: p.tacticalPlans.filter(tp => tp.id !== activePlan.id)}))} className="p-3 bg-red-500/20 text-red-500 rounded-full hover:bg-red-500 hover:text-white transition-all"><Trash2 size={20}/></button>
               </div>

               <div className="flex flex-col md:flex-row gap-8">
                  {/* الملعب */}
                  <div 
                    ref={boardRef}
                    onDragOver={e => e.preventDefault()}
                    onDrop={handleDrop}
                    className="flex-1 aspect-[4/3] bg-emerald-800 rounded-[2rem] border-[6px] border-white/30 relative overflow-hidden shadow-inner"
                    style={{ backgroundImage: 'linear-gradient(rgba(255,255,255,0.05) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,0.05) 1px, transparent 1px)', backgroundSize: '10% 10%' }}
                  >
                     {/* خطوط الملعب */}
                     <div className="absolute inset-4 border-2 border-white/40"></div>
                     <div className="absolute top-1/2 left-4 right-4 h-0.5 bg-white/40"></div>
                     <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-32 h-32 border-2 border-white/40 rounded-full"></div>

                     {/* اللاعبين الموزعين */}
                     {activePlan.positions.map(pos => {
                       const player = players.find(p => p.id === pos.playerId);
                       return (
                         <div key={pos.playerId} 
                           draggable
                           onDragStart={() => setDraggedPlayerId(pos.playerId)}
                           style={{ left: `${pos.x}%`, top: `${pos.y}%` }}
                           className="absolute -translate-x-1/2 -translate-y-1/2 flex flex-col items-center group cursor-move z-20"
                         >
                            <div className="w-12 h-12 bg-orange-600 border-4 border-white rounded-full flex items-center justify-center font-black text-white text-lg shadow-2xl group-hover:scale-110 transition-transform">
                               {player?.number || '??'}
                            </div>
                            <span className="mt-1 bg-black/60 px-2 py-0.5 rounded text-[10px] font-bold text-white whitespace-nowrap">{player?.name.split(' ')[0]}</span>
                         </div>
                       );
                     })}
                  </div>

                  {/* قائمة اللاعبين للسحب */}
                  <div className="w-full md:w-64 space-y-4">
                     <h4 className="font-black text-sm text-orange-500 flex items-center gap-2 border-b border-orange-500 pb-2">
                       <Users size={16}/> قائمة الفئة
                     </h4>
                     <div className="grid grid-cols-2 md:grid-cols-1 gap-2 max-h-[500px] overflow-y-auto custom-scrollbar p-2">
                        {players.map(p => {
                          const isPlaced = activePlan.positions.some(pos => pos.playerId === p.id);
                          return (
                            <div key={p.id}
                              draggable
                              onDragStart={() => setDraggedPlayerId(p.id)}
                              className={`p-3 rounded-xl border-2 flex items-center gap-3 cursor-grab active:cursor-grabbing transition-all ${isPlaced ? 'bg-emerald-500/20 border-emerald-500 opacity-50' : 'bg-white/5 border-white/10 hover:border-orange-500'}`}
                            >
                               <div className="w-8 h-8 bg-slate-900 rounded-lg flex items-center justify-center font-bold text-xs">#{p.number}</div>
                               <span className="text-[10px] font-black">{p.name.split(' ')[0]} {p.name.split(' ')[1]}</span>
                            </div>
                          );
                        })}
                     </div>
                  </div>
               </div>
            </div>
          ) : (
            <div className="h-full flex flex-col items-center justify-center bg-[#001F3F] rounded-[3rem] border-2 border-dashed border-white/10 p-20 opacity-30">
               <MapIcon size={80} className="mb-4" />
               <p className="font-black text-2xl">اختر خطة للبدء في الرسم التكتيكي</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

