const ActivityCountdown: React.FC<{ date: string; time: string }> = ({ date, time }) => {
  const [timeLeft, setTimeLeft] = useState<{ d: number; h: number; m: number; s: number } | null>(null);

  useEffect(() => {
    const calculateTime = () => {
      const target = new Date(`${date}T${time}`);
      const now = new Date();
      const diff = target.getTime() - now.getTime();
      if (diff <= 0) { setTimeLeft(null); return; }
      setTimeLeft({
        d: Math.floor(diff / (1000 * 60 * 60 * 24)),
        h: Math.floor((diff / (1000 * 60 * 60)) % 24),
        m: Math.floor((diff / (1000 * 60)) % 60),
        s: Math.floor((diff / 1000) % 60)
      });
    };
    calculateTime();
    const timer = setInterval(calculateTime, 1000);
    return () => clearInterval(timer);
  }, [date, time]);

  if (!timeLeft) return (
    <div className="flex items-center gap-2 px-3 py-1 bg-emerald-900/30 text-emerald-500 rounded-full animate-pulse border border-emerald-900/50">
      <Zap size={14} />
      <span className="text-[10px] font-black uppercase">النشاط جارٍ</span>
    </div>
  );

  return (
    <div className="flex gap-2 items-center text-[#d1d5db] bg-[#0d141c] px-3 py-1.5 rounded-xl border border-[#1a2530] shadow-inner">
      <div className="flex flex-col items-center"><span className="text-sm font-black tabular-nums">{timeLeft.d}</span><span className="text-[7px] font-bold opacity-50">يوم</span></div>
      <span className="font-bold opacity-20">:</span>
      <div className="flex flex-col items-center"><span className="text-sm font-black tabular-nums">{String(timeLeft.h).padStart(2, '0')}</span><span className="text-[7px] font-bold opacity-50">سا</span></div>
      <span className="font-bold opacity-20">:</span>
      <div className="flex flex-col items-center"><span className="text-sm font-black tabular-nums">{String(timeLeft.m).padStart(2, '0')}</span><span className="text-[7px] font-bold opacity-50">د</span></div>
      <span className="font-bold opacity-20">:</span>
      <div className="flex flex-col items-center"><span className="text-sm font-black tabular-nums text-[#ff6b00]">{String(timeLeft.s).padStart(2, '0')}</span><span className="text-[7px] font-bold opacity-50">ث</span></div>
    </div>
  );
};

