        <div className="fixed inset-0 bg-black/80 backdrop-blur-sm flex items-center justify-center z-[100] p-4">
           <div className="bg-[#0f172a] border border-white/10 rounded-[2.5rem] w-full max-w-2xl max-h-[90vh] overflow-y-auto custom-scrollbar shadow-2xl animate-in zoom-in-95 duration-300">
              <div className="sticky top-0 bg-[#0f172a] p-8 border-b border-white/5 flex justify-between items-center z-10">
                 <h3 className="text-2xl font-bold text-white flex items-center gap-4">
                    <UserPlus className="text-orange-500" /> {editingId ? 'تعديل بيانات العضو' : 'إضافة عضو جديد للفريق'}
                 </h3>
                 <button onClick={() => setIsModalOpen(false)} className="p-2 hover:bg-white/5 rounded-full transition-all text-slate-400 hover:text-white">
                    <X size={24}/>
                 </button>
              </div>

              <form onSubmit={handleSave} className="p-10 space-y-8">
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="space-y-1">
                       <label className={labelClass}>الاسم الكامل</label>
                       <input required className={inputClass} value={formData.name || ''} onChange={e => setFormData({...formData, name: e.target.value})} placeholder="مثال: أحمد محمد علي" />
                    </div>
                    <div className="space-y-1">
                       <label className={labelClass}>الصفة / الدور</label>
                       <select className={inputClass} value={formData.role} onChange={e => setFormData({...formData, role: e.target.value as any})}>
                          <option value="لاعب">لاعب</option>
                          <option value="مدرب">مدرب</option>
                          <option value="مساعد مدرب">مساعد مدرب</option>
                          <option value="مدرب حراس">مدرب حراس</option>
                          <option value="إداري">إداري</option>
                          <option value="طبيب">طبيب</option>
                       </select>
                    </div>
                    <div className="space-y-1">
                       <label className={labelClass}>الفئة</label>
                       <select className={inputClass} value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}>
                          {state.categories.map(c => <option key={c} value={c}>{c}</option>)}
                       </select>
                    </div>
                    {formData.role === 'لاعب' && (
                      <div className="space-y-1">
                         <label className={labelClass}>رقم القميص</label>
                         <input type="number" className={inputClass} value={formData.number || ''} onChange={e => setFormData({...formData, number: parseInt(e.target.value)})} placeholder="0" />
                      </div>
                    )}
                 </div>

                 <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    <div className="space-y-1">
                       <label className={labelClass}>تاريخ الميلاد</label>
                       <input type="date" className={inputClass} value={formData.birthDate || ''} onChange={e => setFormData({...formData, birthDate: e.target.value})} />
                    </div>
                    <div className="space-y-1">
                       <label className={labelClass}>مكان الولادة</label>
                       <input className={inputClass} value={formData.birthPlace || ''} onChange={e => setFormData({...formData, birthPlace: e.target.value})} />
                    </div>
                    <div className="space-y-1">
                       <label className={labelClass}>الخانة (القيد)</label>
                       <input className={inputClass} value={formData.khana || ''} onChange={e => setFormData({...formData, khana: e.target.value})} />
                    </div>
                 </div>

                 <div className="grid grid-cols-1 md:grid-cols-2 gap-6 border-t border-white/5 pt-8">
                    <div className="space-y-1">
                       <label className={labelClass}>الرقم الوطني</label>
                       <input className={inputClass} value={formData.nationalId || ''} onChange={e => setFormData({...formData, nationalId: e.target.value})} />
                    </div>
                    <div className="space-y-1">
                       <label className={labelClass}>الرقم الاتحادي</label>
                       <input className={inputClass} value={formData.federalNumber || ''} onChange={e => setFormData({...formData, federalNumber: e.target.value})} />
                    </div>
                 </div>

                 {formData.role === 'لاعب' && (
                   <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                      <div className="space-y-1">
                         <label className={labelClass}>الطول (سم)</label>
                         <input className={inputClass} value={formData.height || ''} onChange={e => setFormData({...formData, height: e.target.value})} />
                      </div>
                      <div className="space-y-1">
                         <label className={labelClass}>الوزن (كغ)</label>
                         <input className={inputClass} value={formData.weight || ''} onChange={e => setFormData({...formData, weight: e.target.value})} />
                      </div>
                      <div className="space-y-1">
                         <label className={labelClass}>مركز اللعب</label>
                         <input className={inputClass} value={formData.position || ''} onChange={e => setFormData({...formData, position: e.target.value})} placeholder="مثال: هجوم، دفاع.." />
                      </div>
                   </div>
                 )}

                 <div className="space-y-1 pt-4">
                    <label className={labelClass}>ملاحظات إضافية</label>
                    <textarea className={inputClass + " h-32 resize-none"} value={formData.notes || ''} onChange={e => setFormData({...formData, notes: e.target.value})}></textarea>
                 </div>

                 <button type="submit" className="w-full bg-orange-500 text-white py-5 rounded-2xl font-bold text-lg shadow-xl shadow-orange-500/20 hover:bg-orange-600 transition-all flex items-center justify-center gap-3">
                    <Save size={24}/> {editingId ? 'حفظ التغييرات' : 'تثبيت في قاعدة البيانات'}
                 </button>
              </form>
           </div>
        </div>
      )}
    </div>
  );
};

export default SquadManagement;
